 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A vertical 5-bar extends the adjacent horizontal color pattern along its length.
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == 5]
        if len(rs) < 2 or rs != list(range(rs[0], rs[-1] + 1)):
            continue
        top, bottom = rs[0], rs[-1]
        for side in (c - 1, c + 1):
            if not 0 <= side < w:
                continue
            colored = [r for r in range(top, bottom + 1) if grid[r][side] not in (0, 5)]
            if not colored:
                continue
            t, b = min(colored), max(colored)
            if side > c:
                left = side
                while left + 1 < w and grid[t][left + 1] not in (0, 5):
                    left += 1
                left, right = side, left
            else:
                right = side
                while right - 1 >= 0 and grid[t][right - 1] not in (0, 5):
                    right -= 1
                left, right = right, side
            for r in range(top, bottom + 1):
                source_r = t + (r - t) % (b - t + 1)
                for cc in range(left, right + 1):
                    if grid[source_r][cc] not in (0, 5):
                        out[r][cc] = grid[source_r][cc]
            break

    # A horizontal 5-bar extends the adjacent vertical color pattern along its length.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == 5]
        if len(cs) < 2 or cs != list(range(cs[0], cs[-1] + 1)):
            continue
        left, right = cs[0], cs[-1]
        for side in (r - 1, r + 1):
            if not 0 <= side < h:
                continue
            anchors = [c for c in range(left, right + 1) if grid[side][c] not in (0, 5)]
            if not anchors:
                continue
            anchor = anchors[0]
            # Read the contiguous colored vertical template at the anchor column.
            if side > r:
                end = side
                while end + 1 < h and grid[end + 1][anchor] not in (0, 5):
                    end += 1
                t, b = side, end
            else:
                start = side
                while start - 1 >= 0 and grid[start - 1][anchor] not in (0, 5):
                    start -= 1
                t, b = start, side
            seq = [grid[rr][anchor] for rr in range(t, b + 1)]
            for cc in range(left, right + 1):
                for i, value in enumerate(seq):
                    out[t + i][cc] = value
            break
    return out

